#[test]
fn symbol_names_compare_as_gnu_compares_them() {
    let mut vm = Vm::new();
    let wrong: Vec<String> = CASES.iter().filter_map(|&(form, gnu)| {
        let got = vm.eval_source(form).and_then(|v| v.display()).unwrap_or_else(|e| format!("error: {e}"));
        (got != gnu).then(|| format!("{form}: {got}, GNU {gnu}"))
    }).collect();
    assert!(wrong.is_empty(), "{} of {} cases differ from GNU:\n{}", wrong.len(), CASES.len(), wrong.join("\n"));
}
